      if (lookahead == '"') ADVANCE(50);
      if (lookahead == '#') ADVANCE(52);
      if (lookahead == '$') ADVANCE(55);
      if (lookahead == '\\') ADVANCE(14);
      if (lookahead == '\t' ||
          lookahead == '\r' ||
          lookahead == ' ') ADVANCE(51);
